    elif isinstance(value, dt.timedelta):
        try:
            date = now - value
        except (OverflowError, ValueError):
            # Very large timedelta causes date overflow; use a fallback date
            date = None
        delta = value
    else:
        try:
            value = int(value)
            delta = dt.timedelta(seconds=value)
            date = now - delta
        except (ValueError, TypeError, OverflowError):
